<section class="page-header"><div><span class="eyebrow">Global search</span><h1><?= $term?'Results for “'.e($term).'”':'Search Rankers Mind CRM' ?></h1><p>Find leads, clients, projects, staff and invoices from one place.</p></div></section><section class="panel search-page"><form class="large-search" method="get"><i class="fa-solid fa-magnifying-glass"></i><input name="q" value="<?= e($term) ?>" placeholder="Enter at least 2 characters…" autofocus><button class="button button-primary">Search</button></form><?php if($term&&mb_strlen($term)<2):?><div class="inline-alert info">Enter at least 2 characters to search.</div><?php endif;?><div class="search-results"><?php foreach($results as $group):?><section><h2><?= e($group['label']) ?><span><?= count($group['rows']) ?></span></h2><?php foreach($group['rows'] as $row):?><a href="<?= url($group['route'].'/'.$row['id']) ?>"><span class="list-icon"><i class="fa-solid fa-arrow-up-right-from-square"></i></span><span><strong><?= e($row['title']) ?></strong><small><?= e($row['code']) ?></small></span></a><?php endforeach;?><?php if(!$group['rows']):?><p class="empty-inline">No matches in <?= e(strtolower($group['label'])) ?>.</p><?php endif;?></section><?php endforeach;?></div></section>
